create table if not exists public.songs (id uuid primary key default gen_random_uuid(), band_id uuid not null references public.bands(id) on delete cascade, title text not null, status text not null default 'IDEA' check (status in ('IDEA','DRAFT','ARRANGEMENT','READY','ARCHIVED')), bpm integer check (bpm is null or (bpm between 20 and 400)), musical_key text, notes text not null default '', created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists songs_band_id_idx on public.songs(band_id); alter table public.songs enable row level security;
create policy "members read songs" on public.songs for select using (public.is_band_member(band_id)); create policy "members create songs" on public.songs for insert with check (public.is_band_member(band_id) and created_by = auth.uid()); create policy "members update songs" on public.songs for update using (public.is_band_member(band_id)); create policy "members delete songs" on public.songs for delete using (public.is_band_member(band_id));
create or replace function public.my_bands() returns table(id uuid, name text, description text, invite_code text, created_by uuid, created_at timestamptz) language sql stable security definer set search_path = public as $$ select b.id,b.name,b.description,b.invite_code,b.created_by,b.created_at from public.bands b join public.band_members m on m.band_id=b.id where m.user_id=auth.uid() order by b.created_at desc; $$;
grant execute on function public.my_bands() to authenticated;
create or replace function public.create_band(p_name text, p_description text default '') returns public.bands language plpgsql security definer set search_path = public as $$ declare b public.bands; code text; begin if auth.uid() is null then raise exception 'not authenticated'; end if; if length(trim(coalesce(p_name,''))) < 2 then raise exception 'band name is too short'; end if; loop code := upper(substr(encode(gen_random_bytes(5), 'hex'), 1, 8)); exit when not exists(select 1 from public.bands where invite_code = code); end loop; insert into public.bands(name, description, invite_code, created_by) values(trim(p_name), coalesce(p_description,''), code, auth.uid()) returning * into b; insert into public.band_members(band_id, user_id, role) values(b.id, auth.uid(), 'ADMIN'); return b; end; $$;
